import { Spinner } from '@absoluteui/components/spinner';

const host = document.querySelector<HTMLElement>('#results-status');
if (host) {
  const spinner = Spinner.create(host, { label: 'Loading results', delay: 300 });
  void fetch('/api/results').finally(() => {
    spinner.destroy();
  });
}

import { Spinner } from '@absoluteui/components/spinner';

const host = document.querySelector<HTMLElement>('#saving');
if (host) {
  Spinner.create(host, { label: 'Saving changes', showLabel: true, size: 'sm' });
}
